import{c as t,Q as e,j as l,m as o}from"./chunks/framework.rWdQudnF.js";const u=JSON.parse('{"title":"Hello World!","description":"","frontmatter":{"title":"Hello World!"},"headers":[],"relativePath":"案例分析/软件工程真题回顾/Hello World!.md","filePath":"案例分析/软件工程真题回顾/Hello World!.md","lastUpdated":null}'),r={name:"案例分析/软件工程真题回顾/Hello World!.md"};function i(n,a,s,d,h,p){return e(),l("div",null,[...a[0]||(a[0]=[o('<p>结构化建模，即数据流图和R图，当然UML(用例图、类图、序列图等)也需要掌握，如果超纲那就多研究，多做历年案例题，掌握超纲题技巧。</p><p>综合那里的笔记应该是有很大问题，<a href="/arch-exam/综合知识/软件工程/需求工程.html">架构师-备考 软件工程-需求工程</a> 这一章看起来内容也没对上，有空整理一下了。</p><h3 id="结构化三大模型" tabindex="-1">结构化三大模型 <a class="header-anchor" href="#结构化三大模型" aria-label="Permalink to &quot;结构化三大模型&quot;">​</a></h3><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260519234233.png" alt="image.png"></p><h4 id="功能模型-数据流图" tabindex="-1">功能模型（数据流图) <a class="header-anchor" href="#功能模型-数据流图" aria-label="Permalink to &quot;功能模型（数据流图)&quot;">​</a></h4><p>功能、过程、数据流动路径</p><p>DFD 典型特征（一眼认出）：<strong>必有箭头</strong>（数据在移动）、<strong>必有加工</strong>（动词命名：验证、计算、查询）、不会出现条件判断（没有菱形，没有“是/否”分支）、<strong>不会出现状态</strong>（不会写“空闲/忙碌”）、<strong>数据存储只会被箭头连</strong>（不画字段细节）</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260519234620.png" alt="image.png"></p><h4 id="行为模型-状态转换图" tabindex="-1">行为模型（状态转换图） <a class="header-anchor" href="#行为模型-状态转换图" aria-label="Permalink to &quot;行为模型（状态转换图）&quot;">​</a></h4><p>状态、事件、状态转换</p><p>最基础的形状（3个符号）</p><table tabindex="0"><thead><tr><th>符号</th><th>名称</th><th>说明</th></tr></thead><tbody><tr><td>圆角矩形</td><td>状态</td><td>系统在某个时刻的样子（形容词/名词）</td></tr><tr><td>箭头</td><td>转换</td><td>从一个状态到另一个状态</td></tr><tr><td>箭头上文字</td><td>事件/条件</td><td>什么事触发了这个变化（格式：事件 [条件] / 动作）</td></tr></tbody></table><h4 id="数据模型-e-r-图" tabindex="-1">数据模型（E - R 图） <a class="header-anchor" href="#数据模型-e-r-图" aria-label="Permalink to &quot;数据模型（E - R 图）&quot;">​</a></h4><p>一般是数据建模的时候用，比如数据库的字段之类的</p><p>实体、属性、关系</p><p><strong>静态</strong>（数据结构，不随时间变化）</p><h4 id="数据字典" tabindex="-1">数据字典 <a class="header-anchor" href="#数据字典" aria-label="Permalink to &quot;数据字典&quot;">​</a></h4><p>数据元素、结构、定义</p><p><strong>静态定义</strong>（解释性）</p><h3 id="面向对象的分析方法" tabindex="-1">面向对象的分析方法 <a class="header-anchor" href="#面向对象的分析方法" aria-label="Permalink to &quot;面向对象的分析方法&quot;">​</a></h3><h4 id="uml-关系" tabindex="-1">UML 关系 <a class="header-anchor" href="#uml-关系" aria-label="Permalink to &quot;UML 关系&quot;">​</a></h4><ul><li>依赖</li><li>关联</li><li>泛化</li><li>实现</li><li>组合</li><li>聚合</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260519234739.png" alt="image.png"></p><h4 id="uml-图" tabindex="-1">UML 图 <a class="header-anchor" href="#uml-图" aria-label="Permalink to &quot;UML 图&quot;">​</a></h4><ul><li>用例图</li><li>类图</li><li>活动图</li><li>状态图</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260519234837.png" alt="image.png"></p><h3 id="面向对象分析模型" tabindex="-1">面向对象分析模型 <a class="header-anchor" href="#面向对象分析模型" aria-label="Permalink to &quot;面向对象分析模型&quot;">​</a></h3><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260519234932.png" alt="image.png"></p>',28)])])}const m=t(r,[["render",i]]);export{u as __pageData,m as default};
